pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmount, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 beforeBalance;
        try c.balances(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        vm.assume(collectAmount > beforeBalance);
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(c.balances(address(this)) == beforeBalance);
    }

    function testFuzz_run(uint256 depositAmount, uint256 collectAmount) public {
        _run(depositAmount, collectAmount);
    }

    receive() external payable {}
}
